content.append('''<section class="page cover"><img src="food_images/cover-spread.png"><div class="covertext"><div class="eyebrow">THAI FOOD FOR BUSINESS</div><h1>สูตรอาหารไทย<br>สำหรับทำขาย</h1><p>20 เมนูจานเดียว พร้อมวัตถุดิบ วิธีทำ<br>และตัวอย่างต้นทุนต่อกล่อง</p><div class="edition">คู่มือสำหรับผู้เริ่มต้น &nbsp; / &nbsp; 20 RECIPES</div></div></section>''')
content.append('<section class="page intro"><div class="eyebrow">START HERE</div><h2>เริ่มต้นทำอาหารขาย</h2><p>20 สูตรต่อหนึ่งกล่องสำหรับทดลองปรุงและวางแผนขาย เลือกเมนูที่เหมาะกับลูกค้า แล้วชั่งวัตถุดิบและบันทึกต้นทุนจริงทุกครั้ง</p><div class="rule"></div><div class="columns"><div><h3>วิธีใช้หนังสือ</h3><p>น้ำหนักวัตถุดิบเป็นน้ำหนักก่อนปรุง ยกเว้นข้าวสวย เวลาเป็นประมาณต่อหนึ่งกล่อง ภาพอาหารสร้างด้วย AI เพื่อประกอบการจัดเสิร์ฟ อาจมีเครื่องเคียงแตกต่างจากสูตร ตัวเลขโภชนาการเป็นค่าประมาณจากวัตถุดิบในสูตร ไม่ใช่ผลตรวจวิเคราะห์ และเปลี่ยนตามวัตถุดิบและวิธีปรุง</p><h3>คำนวณก่อนตั้งราคา</h3><p>ต้นทุนในเล่มเป็นตัวอย่างสมมติ รวมวัตถุดิบ เครื่องปรุง และบรรจุภัณฑ์ตามรายการ แต่ไม่รวมค่าแรง ค่าเช่า น้ำไฟ ค่าส่ง ค่าธรรมเนียม และของเสีย ส่วนต่างที่แสดงจึงยังไม่ใช่กำไรสุทธิ</p><p><b>ต้นทุนจริง</b> = วัตถุดิบ + บรรจุภัณฑ์ + ค่าใช้จ่ายอื่นต่อกล่อง<br><b>กำไรสุทธิ</b> = รายรับสุทธิ − ต้นทุนจริง</p><h3>ก่อนเริ่มขาย</h3><p>ทดลองสูตรและปรับรส ตรวจราคาจริง แยกอาหารดิบกับอาหารสุก ปรุงเนื้อสัตว์และไข่ให้สุกทั่ว รักษาอุณหภูมิที่เหมาะสม และแจ้งสารก่อภูมิแพ้ตามวัตถุดิบจริง</p></div><div><h3>สารบัญเมนู</h3><div class="toc">'+''.join(f'<div><b>{i:02}</b>{e(r[0])}</div>' for i,r in enumerate(recipes,1))+'</div></div></div><div class="footer"><span>สูตรอาหารไทยสำหรับทำขาย</span><span>02</span></div></section>')
for i,(name,time,ing,steps,cost,price,tip) in enumerate(recipes,1):
 parts=[x.rsplit(' ',1) for x in cost.split(';')]; total=sum(int(v) for _,v in parts)
 costtext='  ·  '.join(f'{e(k)} {v}' for k,v in parts)
 items=''.join('<li>'+e(x)+'</li>' for x in ing.split('; '))
 prep,detail,serving=extra[i-1]
