 content.append(f'''<section class="page recipe"><div class="topline"><span>THAI FOOD FOR BUSINESS</span><span>RECIPE {i:02}</span></div><h2 class="title">{e(name)}</h2><div class="meta">1 กล่อง &nbsp; / &nbsp; {e(time)}</div><img class="hero" src="food_images/{i:02}.png"><div class="body"><div><div class="label">วัตถุดิบ</div><ul class="ingredients">{items}</ul></div><div><div class="label">เตรียมก่อนปรุง</div><div class="notice" style="margin-bottom:4mm">{e(prep)}</div><div class="label">วิธีทำ</div><ol class="steps">{instructions}</ol><div class="label" style="margin-top:4mm">เคล็ดลับ</div><div class="notice">{e(detail)} {e(serving)}</div></div></div><div class="nutrition"><span class="label">คุณค่าโภชนาการโดยประมาณต่อกล่อง</span><div><strong>{kcal}</strong> กิโลแคลอรี &nbsp; / &nbsp; โปรตีน <strong>{protein}</strong> กรัม</div></div><div class="cost"><div class="label">ต้นทุนตัวอย่างต่อกล่อง</div><div class="costline">{costtext} บาท</div><div class="costgrid"><div><strong>{total}</strong> <span>บาท ต้นทุน</span></div><div><strong>{price}</strong> <span>บาท ราคาขายแนะนำ</span></div><div><strong>{price-total}</strong> <span>บาท ส่วนต่างก่อนค่าใช้จ่ายอื่น</span></div></div></div><div class="footer"><span>ภาพประกอบสร้างด้วย AI &nbsp; • &nbsp; ราคาเป็นตัวอย่าง</span><span>{i+2:02}</span></div></section>''')
